{
  "name": "数据采集设备",
  "name_en": "Data Acquisition Device",
  "manufacturer": "",
  "description": "通用实验数据采集设备，用于从实验硬件获取测量数据，并在显微镜成像、数字信号采集或传感器记录等场景中按触发或连续方式输出数据。",
  "description_en": "A generic laboratory data acquisition device used to collect measurement data from experimental hardware and output it in triggered or continuous operation, such as in microscopy imaging, digital signal capture, or sensor logging.",
  "tag_hints": [
    "data acquisition",
    "triggered measurement",
    "microscopy",
    "sensor logging",
    "digital I/O",
    "experimental automation"
  ],
  "actions": [
    {
      "action_name": "auto-abort",
      "description": "尽快停止当前数据采集。",
      "description_en": "Stop the current data acquisition as quickly as possible."
    },
    {
      "action_name": "auto-enable",
      "description": "启用数据采集。",
      "description_en": "Enable data acquisition."
    },
    {
      "action_name": "auto-disable",
      "description": "禁用数据采集。",
      "description_en": "Disable data acquisition."
    },
    {
      "action_name": "auto-set_client",
      "description": "设置数据接收端。",
      "description_en": "Set the data receiving client."
    },
    {
      "action_name": "auto-update_settings",
      "description": "更新采集设置。",
      "description_en": "Update acquisition settings."
    },
    {
      "action_name": "auto-receiveClient",
      "description": "设置数据接收端（兼容接口）。",
      "description_en": "Set the data receiving client (compatibility interface)."
    },
    {
      "action_name": "auto-grab_next_data",
      "description": "获取下一次触发产生的数据。",
      "description_en": "Get the data produced by the next trigger."
    },
    {
      "action_name": "auto-receiveData",
      "description": "接收采集到的数据及时间戳。",
      "description_en": "Receive acquired data and its timestamp."
    }
  ]
}

